INSERT INTO label_nuscenes_meta (
    project_id, batch_id, upload_id, version_dir, meta_object_key, status, remark,
    created_by, updated_by
) VALUES (
    #{projectId}, #{batchId}, #{uploadId}, #{versionDir}, #{metaObjectKey}, #{status}, #{remark},
    #{userId}, #{userId}
)

mapper.update:
UPDATE label_nuscenes_asset_map
SET deleted = 1, updated_by = #{userId}, update_time = NOW()
WHERE deleted = 0 AND upload_id = #{uploadId}

mapper.select:
SELECT m.id, m.project_id AS projectId, m.upload_id AS uploadId, m.asset_id AS assetId, m.sample_token AS sampleToken, m.sample_data_token AS sampleDataToken, m.camera_file_url AS cameraFileUrl, m.camera_asset_id AS cameraAssetId, m.camera_channel AS cameraChannel, ca.file_name AS cameraFileName, m.camera_intrinsic AS cameraIntrinsic, m.camera_rotation AS cameraRotation, m.camera_translation AS cameraTranslation, m.camera_width AS cameraWidth, m.camera_height AS cameraHeight, m.lidar_rotation AS lidarRotation, m.lidar_translation AS lidarTranslation, m.ego_rotation AS egoRotation, m.ego_translation AS egoTranslation FROM label_nuscenes_asset_map m LEFT JOIN label_asset ca ON ca.id = m.camera_asset_id AND ca.deleted = 0 WHERE m.deleted = 0 AND m.asset_id IN
#{assetId}
ORDER BY m.asset_id, m.camera_channel, m.id
